    simp_all only [abs_of_nonneg, abs_of_nonpos, abs_of_nonneg, abs_of_nonpos, sub_nonneg,
      sub_nonpos] <;>
    (try { contradiction }) <;>
    (try {
      -- Use linear arithmetic to find contradictions or solutions
      norm_num at *
      have h₇ : a = 4 ∨ a = 2 := by
        -- Use the quadratic equation to find possible values for a
        apply or_iff_not_imp_left.mpr
        intro h
        apply mul_left_cancel₀ (sub_ne_zero.mpr h)
        nlinarith [sq_nonneg (a - 4), sq_nonneg (a - 2), sq_nonneg (b + 16), sq_nonneg (b + 6),
          sq_nonneg (b + 10)]
      cases' h₇ with h₇ h₇ <;> simp_all [abs_of_nonneg, abs_of_nonpos] <;>
        (try { nlinarith }) <;>
        (try {
          norm_num at *
          <;>
          (try { nlinarith }) <;>
          (try {
            exact Or.inl ⟨by nlinarith, by nlinarith, by nlinarith⟩
          }) <;>
          (try {
            exact Or.inr (Or.inl ⟨by nlinarith, by nlinarith, by nlinarith⟩)
          }) <;>
          (try {
            exact Or.inr (Or.inr ⟨by nlinarith, by nlinarith, by nlinarith⟩)
          })
        })
    }) <;>
    (try {
      norm_num at *
      <;>
      (try {
        exact Or.inl ⟨by nlinarith, by nlinarith, by nlinarith⟩
      }) <;>
      (try {
        exact Or.inr (Or.inl ⟨by nlinarith, by nlinarith, by nlinarith⟩)
      }) <;>
      (try {
        exact Or.inr (Or.inr ⟨by nlinarith, by nlinarith, by nlinarith⟩)
